import { Err } from "../../utils/err.ts";
import type { Result } from "../../types/result.ts";
import { repetitions, type Repeated } from "../../types/segment.ts";
import type { EncodingCharacters } from "../../types/encoding.ts";
import { ParserUtils } from "../../types/parser.ts";
import { CDM as CDM_base } from "../v2.4/CDM.ts";
import { CK, ckParts, components, cxParts, type CX } from "../../utils/composites.ts";

/**
 * CDM - Charge Description Master (HL7 v2.5)
 *
 * Extends the v2.4 CDM: CDM-11 Contract Number (changed).
 */
export class CDM extends CDM_base {
  /**
   * CDM-11 Contract Number (CX, max 250, optional, repeating) (chainable). CK up to v2.4 and CX from
   * v2.5 on; a CK object (its four components are CX's first four) is still accepted.
   */
  override contractNumber(...values: Repeated<string | CX | CK>[]): this {
    this.fields[10] = this.createRepeatingField(
      repetitions(values).map((v) => this.createField(typeof v === "string" ? v : components(v.datatype === "CK" ? ckParts(v) : cxParts(v as CX)))),
    );
    return this;
  }

  /** Parses the input string into a structured instance. */
  static override parse(segmentString: string, encoding: EncodingCharacters): Result<CDM> {
    const parts = segmentString.split(encoding.fieldSeparator);
    if (parts[0] !== "CDM") {
      return { ok: false, err: new Err(`Expected CDM segment, got ${parts[0]}`) };
    }
    const seg = new CDM();
    for (let i = 1; i < parts.length; i++) {
      seg.fields[i - 1] = ParserUtils.parseField(parts[i], encoding);
    }
    return { ok: true, val: seg };
  }
}
